use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let arr = input.as_array().unwrap();
    let mut output = Vec::new();
    let mut finish_times = Vec::new();

    for item in arr {
        let arrival = item[0].as_i64().unwrap();
        let duration = item[1].as_i64().unwrap();

        let mut current_time = arrival;
        for _ in 0..duration {
            if let Some(finish_time) = finish_times.last() {
                current_time = finish_time.max(current_time);
            }
            finish_times.push(current_time);
        }
    }

    Value::Array(output)
}
